package de.corporate.lc.email.domain;
import de.corporate.lc.lc.domain.LetterOfCredit;import jakarta.persistence.*;import java.time.LocalDateTime;import java.util.UUID;
@Entity @Table(name="email_delivery") public class EmailDelivery extends de.corporate.lc.tenant.domain.TenantOwnedEntity{@Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@ManyToOne(optional=false,fetch=FetchType.LAZY)@JoinColumn(name="lc_id")private LetterOfCredit letterOfCredit;@Column(nullable=false,columnDefinition="text")private String recipients;@Column(nullable=false,length=500)private String subject;@Column(columnDefinition="text")private String attachmentNames;@Column(nullable=false,length=20)private String status;@Column(length=1000)private String errorMessage;@Column(nullable=false,length=100)private String sentBy;@Column(nullable=false)private LocalDateTime sentAt=LocalDateTime.now();public UUID getId(){return id;}public LetterOfCredit getLetterOfCredit(){return letterOfCredit;}public void setLetterOfCredit(LetterOfCredit v){letterOfCredit=v;}public String getRecipients(){return recipients;}public void setRecipients(String v){recipients=v;}public String getSubject(){return subject;}public void setSubject(String v){subject=v;}public String getAttachmentNames(){return attachmentNames;}public void setAttachmentNames(String v){attachmentNames=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public String getErrorMessage(){return errorMessage;}public void setErrorMessage(String v){errorMessage=v;}public String getSentBy(){return sentBy;}public void setSentBy(String v){sentBy=v;}public LocalDateTime getSentAt(){return sentAt;}}
